from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)

        prefix = [0] * (n + 1)
        for i, s in enumerate(skill):
            prefix[i + 1] = prefix[i] + s

        start = 0
        for j in range(len(mana) - 1):
            delay = 0
            for i in range(n):
                delay = max(delay, prefix[i + 1] * mana[j] - prefix[i] * mana[j + 1])
            start += delay

        return start + prefix[n] * mana[-1]
